#!/usr/bin/env bash
#
# Interactive Supabase Cloud Setup Wizard for Monk's Dream Jazz Bar POS.
# Generated by the /wizard skill.
#
# Walks you step-by-step through creating a Supabase project, capturing credentials,
# linking the CLI, applying Phase 1 migrations and seed data, and generating types.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

TOTAL_STAGES=5
_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-frontend/.env}"
WRITTEN_ENV=()
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  This wizard guides you through setting up Supabase Cloud for Phase 1.\n' "$DIM"
  printf '  It will open the necessary dashboard pages, configure credentials,\n'
  printf '  link the Supabase CLI, push migrations, and run seed data.%s\n\n' "$RESET"
  pause "Press Enter when you are ready to begin..."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ Opening in browser:%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    elif command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "Could not open browser automatically. Please visit: $url"
}

pause() {
  printf '\n  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then value="${value:1:${#value}-2}"; fi
  printf '%s' "$value"
}

ask() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  [[ -n "$current" ]] && printf '%s[Enter keeps current: %s]%s ' "$DIM" "$current" "$RESET"
  read -e -r input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current saved value]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ Wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Supabase Setup & Phase 1 Execution Complete!%s\n\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} )) && note "Configured values in $ENV_FILE: ${WRITTEN_ENV[*]}"
  printf '\n'
  say "Next steps:"
  say "1. Run 'pnpm --filter @monks/frontend start -c' to test the tablet frontend."
  say "2. Open Supabase Dashboard to view your seeded tables, users, and catalog."
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

banner "Monk's Dream POS — Supabase Cloud Wizard"

# Stage 1: Create Supabase Project
stage "Create Supabase Project"
say "We will open the Supabase dashboard to create your project."
step "Log in to supabase.com if not already signed in."
step "Click 'New project'."
step "Name: Monks-Dream-POS (or your preference)."
step "Database Password: Choose a strong password and save it in a safe place."
step "Region: Pick the nearest region (e.g., Singapore, Frankfurt, US East)."
step "Wait ~1-2 minutes for project provisioning to finish."
open_url "https://supabase.com/dashboard/projects"
pause "Press Enter once your project is active and ready in the dashboard..."

# Stage 2: Capture Project Ref & API Keys
stage "Capture Project Reference & API Keys"
say "Now we will retrieve your Project Reference ID and Publishable Anon Key."
step "Go to Project Settings (gear icon in left sidebar) → Data API / API."
step "Copy the 'Project URL' (e.g. https://abcdefghijklmnopqrst.supabase.co)."
step "The Project Reference is the 20-character ID in that URL."
step "Copy the 'anon public' API Key."
open_url "https://supabase.com/dashboard/projects"

ask PROJECT_REF "Paste your Project Reference ID (e.g., abcdefghijklmnopqrst):"
ask_secret SUPABASE_ANON_KEY "Paste your anon/public API Key:"

SUPABASE_URL="https://${PROJECT_REF}.supabase.co"
write_env "EXPO_PUBLIC_SUPABASE_URL" "$SUPABASE_URL"
write_env "EXPO_PUBLIC_SUPABASE_ANON_KEY" "$SUPABASE_ANON_KEY"
pause "Credentials saved to frontend/.env! Press Enter to continue..."

# Stage 3: Link Supabase CLI
stage "Link Supabase CLI"
say "Now linking the local Supabase CLI to your remote project."
step "If you haven't logged into Supabase CLI, it will prompt you with a login URL."
note "Running: npx supabase login"
npx supabase login || warn "Login command completed or already authenticated."

printf '\n'
note "Linking project reference: $PROJECT_REF"
say "You will be prompted to enter your database password:"
npx supabase link --project-ref "$PROJECT_REF"
pause "Project successfully linked! Press Enter to apply Phase 1 schema..."

# Stage 4: Apply Migrations & Seed Data
stage "Apply Phase 1 Schema & Seed Catalog"
say "Pushing 20261017000000_init_pos_schema.sql to Supabase Cloud..."
npx supabase db push

printf '\n'
say "Executing comprehensive catalog seed (users, 25 tables, stock, recipe BOMs)..."
if npx supabase db execute --file ./supabase/seed.sql; then
  printf '  %s✓ Seed script applied successfully!%s\n' "$GREEN" "$RESET"
else
  warn "CLI seed execution had an issue. You can paste supabase/seed.sql into the Supabase SQL Editor."
fi
pause "Database migrated and seeded! Press Enter to generate TypeScript types..."

# Stage 5: Generate TypeScript Types & Verify Build
stage "Generate TypeScript Types & Verify Monorepo"
say "Generating database.types.ts from remote schema..."
pnpm supabase:types

printf '\n'
say "Verifying TypeScript build across all packages..."
pnpm build

finish
}

run_wizard "$@"; exit
